g=[[0]*w for _ in range(h)]
# Original four identical 5x5 motifs, preserving their locations.
origins=[(2,14,4),(7,21,8),(9,2,3),(12,9,1)]
shape=[[(0,c) for c in range(5)],[(1,2)],[(2,c) for c in range(1,4)],[(3,c) for c in range(5)],[(4,2)]]
for r0,c0,color in origins:
